<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>VoltSeal ROI Calculator</title>
<script src="https://cdn.tailwindcss.com"></script>
<style>
  html,body{background:#F7F3EC;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#0E3B2E}
  input[type=number]{-moz-appearance:textfield}
  input[type=number]::-webkit-outer-spin-button,input[type=number]::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
  .tabnum{font-variant-numeric:tabular-nums}
</style>
</head>
<body>
<div id="app" class="min-h-screen w-full"></div>
<script>
const LOGO="data:image/png;base64,";

function formatINR(n){
  if(!isFinite(n))return"0";
  const r=Math.round(n),neg=r<0,s=Math.abs(r).toString();
  if(s.length<=3)return(neg?"-":"")+s;
  const last3=s.slice(-3),rest=s.slice(0,-3);
  return(neg?"-":"")+rest.replace(/\B(?=(\d{2})+(?!\d))/g,",")+","+last3;
}
function formatNumComma(n,d=2){if(!isFinite(n))return"0";return n.toLocaleString("en-IN",{minimumFractionDigits:d,maximumFractionDigits:d})}

const state={power:"500",dgHrs:"2",days:"250",dgErr:"",daysErr:""};

function calc(){
  const P=Math.max(0,parseFloat(state.power)||0);
  const dH=Math.max(0,parseFloat(state.dgHrs)||0);
  const D=Math.max(0,parseInt(state.days,10)||0);
  const bessSize=(P*dH)/0.81;
  const energyPerDay=bessSize;
  const annualEnergy=energyPerDay*D;
  const annualSavings=annualEnergy*20;
  const capex=bessSize*19000;
  const paybackYears=annualSavings>0?capex/annualSavings:0;
  const paybackMonths=paybackYears*12;
  const netProfit10=annualSavings*10-capex;
  return{bessSize,energyPerDay,annualEnergy,annualSavings,capex,paybackYears,paybackMonths,netProfit10};
}

function kpi(value,label,sub,priority){
  const sizeCls=priority==="high"?"text-[clamp(1.6rem,2.6vw,2.6rem)]":priority==="medium"?"text-[clamp(1.35rem,2vw,2rem)]":"text-[clamp(1.15rem,1.6vw,1.6rem)]";
  return `<div class="flex flex-col justify-center rounded-[20px] bg-white p-5 shadow-[0_4px_20px_-8px_rgba(14,59,46,0.15)] ring-1 ring-black/[0.03]">
    <div class="${sizeCls} font-bold tracking-tight text-[#0E3B2E] whitespace-nowrap leading-tight tabnum">${value}</div>
    ${sub?`<div class="mt-0.5 text-sm font-medium text-[#184D3B]/70 whitespace-nowrap">${sub}</div>`:""}
    <div class="mt-2 text-[clamp(0.75rem,0.9vw,0.9rem)] font-medium uppercase tracking-wide text-neutral-500">${label}</div>
  </div>`;
}

function inputCard(id,label,unit,value,placeholder,step,error){
  return `<div class="rounded-2xl bg-white p-4 shadow-[0_6px_24px_-12px_rgba(0,0,0,0.25)]">
    <div class="mb-2 flex items-baseline justify-between">
      <label class="text-sm font-semibold text-[#0E3B2E]">${label}</label>
      <span class="text-xs font-medium uppercase tracking-wider text-neutral-500">${unit}</span>
    </div>
    <input id="${id}" type="number" inputmode="decimal" min="0" step="${step}" value="${value}" placeholder="${placeholder}"
      class="w-full rounded-lg border border-neutral-200 bg-neutral-50/60 px-3 py-2.5 text-lg font-semibold text-[#0E3B2E] outline-none tabnum focus:border-[#184D3B] focus:bg-white focus:ring-2 focus:ring-[#184D3B]/20" />
    <div class="overflow-hidden text-[13px] font-medium text-[#DC2626] transition-all duration-200 ${error?"mt-1.5 max-h-10 opacity-100":"max-h-0 opacity-0"}">${error||""}</div>
  </div>`;
}

function render(){
  const c=calc();
  const app=document.getElementById("app");
  const active=document.activeElement&&document.activeElement.id;
  const caret=active?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;
  app.innerHTML=`
  <div class="mx-auto flex min-h-screen max-w-[1600px] flex-col lg:flex-row">
    <aside class="flex w-full flex-col p-6 lg:w-[35%] lg:p-8" style="background:linear-gradient(160deg,#0E3B2E 0%,#184D3B 60%,#0E3B2E 100%)">
      <div class="p-6"><img src="${LOGO}" alt="VoltSeal" class="block h-auto" style="max-width:220px;object-fit:contain" /></div>
      <div class="mt-6 flex flex-col gap-4">
        ${inputCard("power","Power Requirement","kW",state.power,"500","0.01","")}
        ${inputCard("dgHrs","DG Usage Per Day","Hours",state.dgHrs,"2","0.01",state.dgErr)}
        ${inputCard("days","DG Operational Days","Days",state.days,"250","1",state.daysErr)}
      </div>
      <div class="mt-auto pt-8 text-xs text-white/50">© ${new Date().getFullYear()} VoltSeal Energy</div>
    </aside>
    <main class="flex-1 p-6 lg:p-10">
      <header class="mb-6">
        <h1 class="text-2xl font-bold tracking-tight text-[#0E3B2E]">ROI Calculator</h1>
        <p class="mt-1 text-sm text-neutral-600">Executive dashboard — VoltSeal Battery Energy Storage Systems</p>
      </header>
      <div class="grid grid-cols-1 gap-4 md:grid-cols-3">
        ${kpi("₹"+formatINR(c.annualSavings),"Annual Savings",null,"high")}
        ${kpi(c.paybackYears.toFixed(2)+" Years","Payback Period",c.paybackMonths.toFixed(1)+" Months","high")}
        ${kpi("₹"+formatINR(c.netProfit10),"Net Profit After 10 Years",null,"high")}
      </div>
      <div class="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
        ${kpi(formatNumComma(c.bessSize,2),"BESS Size","kWh","medium")}
        ${kpi(formatNumComma(c.energyPerDay,2),"Energy Saved Per Day","kWh / day","medium")}
        ${kpi(formatNumComma(c.annualEnergy,0),"Annual Energy Saved","kWh / year","medium")}
      </div>
      <div class="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
        ${kpi("₹"+formatINR(c.capex),"CAPEX",null,"medium")}
      </div>
      <p class="mt-8 text-xs text-neutral-500">Assumption: Diesel generation cost considered at ₹32 per kWh.</p>
    </main>
  </div>`;
  bind();
  if(active){const el=document.getElementById(active);if(el){el.focus();try{el.setSelectionRange(caret[0],caret[1])}catch(e){}}}
}

function handlePower(v){if(v===""||/^\d*\.?\d*$/.test(v))state.power=v;render()}
function handleDg(v){
  if(v===""){state.dgHrs="";state.dgErr="";return render()}
  let n=parseFloat(v);if(isNaN(n)||n<0)return;
  let err="";if(n>4){n=4;err="Maximum DG usage per day is 4 hours."}
  state.dgHrs=String(n);state.dgErr=err;render();
}
function handleDays(v){
  if(v===""){state.days="";state.daysErr="";return render()}
  let n=parseInt(v,10);if(isNaN(n)||n<0)return;
  let err="";if(n>365){n=365;err="Maximum DG operational days is 365 days."}
  state.days=String(n);state.daysErr=err;render();
}

function bind(){
  document.getElementById("power").addEventListener("input",e=>handlePower(e.target.value));
  document.getElementById("dgHrs").addEventListener("input",e=>handleDg(e.target.value));
  document.getElementById("days").addEventListener("input",e=>handleDays(e.target.value));
}

render();
</script>
</body>
</html>
